Suppose for each $i$, there exists a rational expression
$\hat{\lambda}_i/q_i$ for the $i$th player's Lagrange multiplier vector.
Since $q_{i}(x)\lambda_{i,j}=\hat{\lambda}_i(x)$
and $q_i(x)\ge0$ for all $x\in X$,
the following holds for all KKT points
\be
\label{eq:KKTrational}
\left\{
\begin{array}{l}
q_i(x)\nabla_{x_i} f_i(x)-\sum\nolimits_{j=1}^{m_i}
 \hat{\lambda}_{i,j}(x)\nabla_{x_i} g_{i,j}(x)=0 \, (i\in[N]),\\
\hat{\lambda}_i(x)\perp g_i(x),g_{i,j}(x)=0 \, (j\in\mathcal{E}_i,i\in[N]),\\
g_{i,j}(x)\ge0,\hat{\lambda}_{i,j}(x)\ge0\,(j\in\mathcal{I}_i,i\in[N]).
\end{array}
\right.
\ee

The optimality conditions (\ref{eq:KKTwithLMalp})
can be equivalently expressed as
\be
\label{eq:KKTpartial}
\left\{
\begin{array}{l}
\nabla_{x_i} f_i(x)-\sum_{j=1}^{m_i}\hat{\lambda}_{i,j}(\allx)\nabla_{x_i} g_{i,j}(x)=0 \, (i\in[N]),\\
\hat{\lambda}_i(\allx)\perp g_i(x),g_{i,j}(x)=0 \, (j\in\mathcal{E}_i, i\in[N]),\\
g_{i,j}(x)\ge0,\hat{\lambda}_{i,j}(\allx)\ge0\,(j\in\mathcal{I}_i,i\in[N]).
\end{array}
\right.
\ee

\begin{thm}
\label{tm:KKTSDPconv}
